<template><div class="modal-backdrop" @mousedown.self="$emit('close')"><form class="modal profile-dialog profile-editor" @submit.prevent="$emit('save',form)"><div class="modal-head"><div><h2>Meu perfil</h2><p>Sua identidade pessoal em todos os workspaces.</p></div><button type="button" @click="$emit('close')"><X/></button></div><div class="profile-detail"><div class="profile-avatar-editor"><Avatar :member="preview"/><label title="Alterar foto"><Camera/><input type="file" accept="image/*" @change="upload"/></label></div><div class="profile-name-row"><h3>{{form.name}}</h3><Pencil/></div><p>{{account?.email}}</p><div class="avatar-gallery"><span>Avatares sugeridos</span><div><button v-for="n in 6" :key="n" type="button" :class="{selected:form.avatar===`suggested:${n-1}`}" @click="form.avatar=`suggested:${n-1}`"><i :style="avatarStyle(n-1)"/></button></div></div><dl><div><dt>Nome completo</dt><dd><input v-model="form.name" required/></dd></div><div><dt>Cargo profissional</dt><dd><input v-model="form.job" required/></dd></div><div><dt>Permissão neste workspace</dt><dd>{{role}}<small>Gerenciada pelo administrador do workspace</small></dd></div></dl></div><div class="modal-actions"><span/><button type="button" class="cancel" @click="$emit('close')">Cancelar</button><button class="primary-btn"><Check/>Salvar perfil</button></div></form></div></template>
<script setup lang="ts">import{computed,reactive}from"vue";import{Camera,Check,Pencil,X}from"lucide-vue-next";import Avatar from"./Avatar.vue";import type{Account,Member,Role}from"../stores/taskflow";const props=defineProps<{account?:Account;member?:Member;role:Role}>();defineEmits(["close","save"]);const form=reactive({name:props.account?.name||"",job:props.account?.job||"",avatar:props.account?.avatar}),preview=computed<Member>(()=>({...props.member!,name:form.name,job:form.job,avatar:form.avatar,initials:form.name.split(" ").slice(0,2).map(v=>v[0]).join("").toUpperCase()}));const avatarStyle=(n:number)=>({backgroundImage:"url(/avatar-suggestions.png)",backgroundSize:"300% 200%",backgroundPosition:`${n%3*50}% ${Math.floor(n/3)*100}%`});function upload(e:Event){const file=(e.target as HTMLInputElement).files?.[0];if(!file)return;const reader=new FileReader();reader.onload=()=>form.avatar=String(reader.result);reader.readAsDataURL(file)}</script>
